    if gasn.ngasn[idgs] == 54:
      gfrac = ratio.frac[idgs]
  gfrac = gfrac / 100.0
  # DIMER NORMALISATION
  # PURE MERCURY  EANDE=0.00221
  # N2-HG MIX     EANDE=0.00162
  # HE-HG MIX     EANDE=0.00067
  eande = 0.0022100000642240047
  dnorm = gfrac * (573.0 / (273.1499938964844 + inpt.tempc)) * inpt.torr / 760.0
