      b = (xexc6[j - 1] * yexc6[j] - xexc6[j] * yexc6[j - 1]) / (xexc6[j - 1] - xexc6[j])
      qin[6, i] = (a * en + b) * 1e-16
    # EXC 1S0
    qin[7, i] = 0.0
    if not (en <= ein[7]):
      block L760:
        fdo j, 2, nexc7:
