      qin[8, i] = (a * en + b) * 1e-16
    q[1, i] = q[2, i] + q[3, i] + qin[1, i] + qin[2, i] + qin[3, i] + qin[4, i] + qin[5, i] + qin[6, i] + qin[7, i] + qin[8, i]
  if inpt.efinal < ein[8]: nin = 7
  if inpt.efinal < ein[7]: nin = 6
